    #region Device Messaging
    /// <summary>
    /// Sends a SCPI message to the device through Core, doing nothing but logging when the
    /// device is unavailable.
    /// </summary>
    /// <remarks>
    /// <para>
    /// Checking <see cref="DaqifiDevice.IsConnected"/> and then calling <c>Send</c> is a race, not
    /// a guard: Core documents that <see cref="DaqifiDevice.Send{T}"/> throws
    /// <see cref="DeviceNotConnectedException"/> "with <c>IsShuttingDown</c> set, when a disconnect,
    /// dispose or auto-reconnect on another thread tears the send path down after this call has
    /// passed its connectivity guard — an ordinary race a long-lived sender should expect, not a
    /// defect". Every caller of this method is a UI command or property setter
    /// (<see cref="AddChannel"/>, <see cref="RemoveChannel"/>, <see cref="AddChannels"/>,
    /// <see cref="RemoveAllChannels"/>, <see cref="SetFriendlyName"/>, the mode switches), so an
    /// escaping throw reaches <c>Dispatcher.UIThread.UnhandledException</c> and ends the process
    /// (issue #291). Core 1.7.0 offers no try/no-throw <c>Send</c> overload, so the app owns this.
    /// </para>
    /// <para>
    /// Routed through <see cref="ExecuteDeviceCommand(string, Action{CoreStreamingDevice})"/> so
    /// unavailability behaves the same here as it already does for the DIO and PWM commands, and
    /// so all three transports answer the question once instead of three times over. Swallowing is
    /// right rather than merely convenient: <see cref="DaqifiDevice.Send{T}"/> is documented
    /// fire-and-forget — it returns before the write happens and reports delivery failures only via
    /// <c>SendFailed</c> — so a caller never had a synchronous success signal to lose.
    /// </para>
    /// <para>
    /// Virtual only so test doubles can capture traffic without a transport; the three real
    /// transports share this implementation. The command text is logged because a swallowed command
    /// is otherwise undiagnosable; nothing sensitive travels this path (Wi-Fi credentials go
    /// through Core's <c>UpdateNetworkConfigurationAsync</c>, never <c>SendMessage</c>).
    /// </para>
    /// </remarks>
    /// <param name="message">The SCPI message to send.</param>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.SendMessage
    // @port: Daqifi.Desktop.Device.SerialDevice.SerialStreamingDevice.SendMessage
    // @port: Daqifi.Desktop.Device.UsbDevice.UsbStreamingDevice.SendMessage
    // @port: Daqifi.Desktop.Device.WiFiDevice.DaqifiStreamingDevice.SendMessage
    protected virtual void SendMessage(IOutboundMessage<string> message)
    {
        ExecuteDeviceCommand($"send '{message.Data}'", coreDevice => coreDevice.Send(message));
    }
    #endregion

    #region Core Connection Template
    /// <summary>
    /// Connects to the device using the shared Core connect/wire/initialize skeleton:
    /// tear down any previous connection, create the transport-specific Core device
    /// (<see cref="CreateCoreDevice"/>), subscribe Core events, initialize desktop state, run
    /// Core's async initialization, then run the optional transport-specific post-initialize
    /// step (<see cref="OnCoreDeviceInitialized"/>). On any failure the attempt is logged
    /// (<see cref="LogConnectFailure"/>) and fully cleaned up (<see cref="CleanupConnection"/>).
    /// </summary>
    /// <remarks>
    /// Synchronous by contract: <see cref="ConnectionManager"/> invokes <c>Connect()</c> from
    /// <c>Task.Run</c>, which is what makes blocking on <c>InitializeAsync()</c> safe here.
    /// Do not call this from the UI thread.
    /// </remarks>
    /// <returns><c>true</c> when the device connected and initialized; otherwise <c>false</c>.</returns>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.Connect
    public virtual bool Connect()
    {
        // Ensure any previous connection state is cleaned up first
        CleanupConnection();

        try
        {
            var coreDevice = CreateCoreDevice();
            if (coreDevice == null)
            {
                return false;
            }

            CoreDevice = coreDevice;

            // Point any already-attached diagnostics subscriber at THIS session's Core device.
            // Connect() is a template that can run again on the same wrapper (reconnect), and the
            // ErrorOccurred/SendFailed bridge binds lazily on first subscribe — see RebindDiagnostics.
            RebindDiagnostics();

            coreDevice.ChannelsPopulated += OnCoreChannelsPopulated;
            coreDevice.MessageReceived += OnCoreMessageReceived;
            coreDevice.StatusChanged += OnCoreStatusChanged;

            InitializeDeviceState();

            // Blocking on Core's async initialization is safe because Connect() is invoked
            // from Task.Run by ConnectionManager (see remarks).
            coreDevice.InitializeAsync().GetAwaiter().GetResult();

            OnCoreDeviceInitialized();

            // Re-read Core's metadata now that initialization is complete. The only other hydrate
            // runs from ChannelsPopulated, which Core raises while waiting for the device's first
            // status message — i.e. BEFORE it asks the device to describe itself
            // (DaqifiDevice.InitializeAsync: WaitForChannelsPopulatedAsync, then
            // ReadCapabilityDocumentAsync). What that later step brings back is the capability
            // document, and it is the only thing in Core that moves Capabilities off the board
            // table — including MaxSamplingRate, which this wrapper's rate guard clamps against.
            // Core re-raises ChannelsPopulated after applying a document only when the document
            // adds analog-output channels, so on a board without those this call is the wrapper's
            // one chance to see it; drop it and the wrapper keeps the board-table defaults and a
            // null CapabilityDocument for the whole session. The ceiling itself is the device's to
            // state, never a figure worth writing down here — read Capabilities.MaxSamplingRate.
            // Pinned by AbstractStreamingDeviceMetadataHydrationTests.
            HydrateDeviceMetadata(coreDevice.Metadata);

            // Take ownership of the enabled-channel set before anything can render it. Must run
            // before RaiseIsConnectedChanged() below: that is what puts the device in front of the
            // UI, and the channel tiles read IsActive straight through to Core's IsEnabled.
            AdoptDeviceChannelSet(coreDevice);

            // Notify IsConnected on connect. Core sets Status=Connected inside CreateCoreDevice/
            // InitializeAsync — the first (and possibly only) transition can fire before the
            // StatusChanged handler is attached above, so raise it explicitly here too (issue #3).
            RaiseIsConnectedChanged();
            return true;
        }
        catch (Exception ex)
        {
            LogConnectFailure(ex);
            CleanupConnection();
            return false;
        }
    }

    /// <summary>
    /// Disconnects from the device: stops streaming, unsubscribes Core events, clears
    /// channels, and tears down the connection via <see cref="CleanupConnection"/>.
    /// </summary>
    /// <returns><c>true</c> when the disconnect completed; otherwise <c>false</c>.</returns>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.Disconnect
    public virtual bool Disconnect()
    {
        try
        {
            StopStreaming();
        }
        catch (Exception ex)
        {
            // A dead transport (e.g., USB unplugged mid-stream) must not abort teardown.
            AppLogger.Warning(ex, $"Error stopping streaming while disconnecting DAQiFi device {DisplayIdentifier}");
        }

        try
        {
            // Unsubscribe before clearing channels so a late ChannelsPopulated event
            // cannot repopulate the list after the clear.
            if (CoreDevice != null)
            {
                UnsubscribeCoreDeviceEvents(CoreDevice);
            }

            // Clear channels to prevent ghost channels on reconnect (Issue #29)
            AppLogger.Information($"Cleared {DataChannels.Count} channels for device {DeviceSerialNo}");
            DataChannels.Clear();

            CleanupConnection();
            return true;
        }
        catch (Exception ex)
        {
            AppLogger.Error(ex, $"Error disconnecting from DAQiFi device {DisplayIdentifier}");
            return false;
        }
    }

    /// <summary>
    /// Creates and connects the transport-specific Core streaming device for the shared
    /// <see cref="Connect"/> template. Return <c>null</c> (after logging) to fail without an
    /// exception, or throw to route the failure through <see cref="LogConnectFailure"/>.
    /// Intermediate state assigned before a throw (e.g., a transport, or
    /// <see cref="CoreDevice"/> itself) is torn down by <see cref="CleanupConnection"/>.
    /// The default returns <c>null</c>; devices using the shared template must override.
    /// </summary>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.CreateCoreDevice
    protected virtual CoreStreamingDevice? CreateCoreDevice() => null;

    /// <summary>
    /// Called by <see cref="Connect"/> after Core's <c>InitializeAsync()</c> completes.
    /// Default does nothing; serial overrides to block until the device reports its
    /// initial status message.
    /// </summary>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.OnCoreDeviceInitialized
    protected virtual void OnCoreDeviceInitialized()
    {
    }

    /// <summary>
    /// Brings the device's enabled-channel set in line with the app's, which starts empty: a
    /// freshly connected device has nothing active until the user picks channels.
    /// </summary>
    /// <remarks>
    /// <para>
    /// Required since Core 1.4.0 (daqifi-core#409), which resyncs analog <c>IsEnabled</c> from the
    /// device's own <c>analog_in_port_enabled</c> mask on every status message; this app pins Core
    /// 1.7.0. Firmware persists its enabled set, so from the first status message onward the app
    /// inherited an active set it never asked for.
    /// </para>
    /// <para>
    /// That broke channel activation outright (upstream issue #811, ported as #165).
    /// <see cref="AnalogChannel.IsActive"/> reads straight through to Core's flag, so every tile
    /// rendered active while nothing was subscribed to <c>LoggingManager</c>;
    /// <c>ChannelsPaneViewModel.SelectAll</c> skips tiles already reporting active, so it became a
    /// no-op, no channel was ever subscribed, and <c>DaqifiViewModel.CanToggleLogging</c> — which
    /// counts subscribed channels — left Start Logging disabled with no way for the user to enable
    /// it. The user could not log at all.
    /// </para>
    /// <para>
    /// Reconciling toward the app rather than the device matches what already happened before
    /// Core 1.4.0 made the device's view visible: the first enable sends a set-replace mask
    /// computed from the app's own state, so the app has always owned the enabled set. This just
    /// makes that ownership explicit at connect instead of implicit at first click.
    /// </para>
    /// <para>
    /// Best-effort: a device that refuses the command is logged and left alone rather than failing
    /// the connection, since the user can still pick channels by hand.
    /// </para>
    /// <para>
    /// Internal rather than private so <c>Daqifi.Avalonia.Tests</c> can drive it against a real
    /// Core device whose channels report themselves enabled — the device state that triggers this
    /// is one the bench hardware does not present (see the PR), so the test is the only place the
    /// original failure is reproduced.
    /// </para>
    /// </remarks>
    /// <param name="coreDevice">The freshly initialized Core device.</param>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.AdoptDeviceChannelSet
    internal void AdoptDeviceChannelSet(CoreStreamingDevice coreDevice)
    {
        ArgumentNullException.ThrowIfNull(coreDevice);

        var deviceReportedActive = coreDevice.Channels.Count(channel => channel.IsEnabled);
        if (deviceReportedActive == 0)
        {
            return;
        }

        try
        {
            coreDevice.DisableAllChannels();
            AppLogger.Information(
                $"Cleared {deviceReportedActive} channel(s) the device reported as already enabled on " +
                $"{DisplayIdentifier}, so the app starts from its own empty active set (issue #165).");
        }
        catch (Exception ex) when (!IsConnectionFatal(coreDevice, ex))
        {
            AppLogger.Warning(ex,
                $"Could not clear the device-reported enabled channels on {DisplayIdentifier}. " +
                "Channel tiles may show as active before any channel has been selected.");
        }
    }

    /// <summary>
    /// Whether a failure raised while adopting the channel set means the connection itself is gone,
    /// rather than the device merely declining the command.
    /// </summary>
    /// <remarks>
    /// The distinction decides whether <see cref="Connect"/> can still return <c>true</c>. Adoption
    /// is best-effort — a device that refuses is survivable, because the user can still pick
    /// channels by hand — but a dropped transport is not: swallowing it would let
    /// <see cref="Connect"/> report success and <c>ConnectionManager</c> add a device that is
    /// already gone, skipping <see cref="LogConnectFailure"/> and <see cref="CleanupConnection"/>.
    /// Used as an exception filter so a fatal failure propagates to the connect template's own
    /// catch with its stack intact, instead of being rethrown from a nested frame.
    /// <para>
    /// Delegating to Core turned calls that used to no-op while disconnected into calls that throw
    /// (<see cref="DeviceNotConnectedException"/>, daqifi-core#395), so every such site has to
    /// decide explicitly what a disconnect means for it.
    /// </para>
    /// </remarks>
    /// <param name="coreDevice">The device the command was issued against.</param>
    /// <param name="ex">The failure raised by that command.</param>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.IsConnectionFatal
    internal static bool IsConnectionFatal(CoreStreamingDevice coreDevice, Exception ex) =>
        !coreDevice.IsConnected
        || ex is DeviceNotConnectedException
        || IsTransportDisconnectedError(ex);

    /// <summary>
    /// Logs a failure of the shared <see cref="Connect"/> template. Default logs an error;
    /// transports override to add context or downgrade user/environmental conditions
    /// (e.g., a COM port that disappeared) to warnings.
    /// </summary>
    /// <param name="ex">The exception that failed the connection attempt.</param>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.LogConnectFailure
    protected virtual void LogConnectFailure(Exception ex)
    {
        AppLogger.Error(ex, $"Problem connecting to DAQiFi device {DisplayIdentifier}");
    }

    // @port-divergence: the SCPI-init connect failure is classified by the typed
    // Daqifi.Core.Device.ScpiInitializationErrorException — see the `case ScpiInitializationErrorException`
    // arms in SerialStreamingDevice / DaqifiStreamingDevice — rather than by upstream's
    // `case InvalidOperationException when <message-match>`. As of the pinned Core (1.3.0), that typed
    // exception derives from Exception, not InvalidOperationException, so the upstream type-pattern
    // would not match it; matching the type is both correct here and Core's intended classification
    // hook. Keep the typed match across Core bumps unless Core changes the exception's type. (Upstream
    // carries the same InvalidOperationException match: daqifi/daqifi-desktop#775.)

    /// <summary>
    /// True when <paramref name="ex"/> is Core's transport reporting that the connection dropped
    /// mid-initialization. Core's <see cref="TransportNotConnectedException"/> — the device unplugged,
    /// powered off, WiFi/AP dropped, or a DTR-triggered MCU reset closed the link while Core was still
    /// bringing the session up. Environmental, not an app bug, so the connect path downgrades it to a
    /// warning. Matched by TYPE, not message: Core throws this same exception with several wordings
    /// ("… is not connected.", "… is no longer connected.") from the serial/TCP transports AND from
    /// DaqifiDevice.ExecuteTextCommandAsync during the SCPI-init exchange, so a substring match would
    /// miss the common silent-drop-mid-init case (the exact #588/#740 scenario). Shared by both transports.
    /// </summary>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.IsTransportDisconnectedError
    internal static bool IsTransportDisconnectedError(Exception ex) => ex is TransportNotConnectedException;

    /// <summary>
    /// Tears down the Core device created by <see cref="Connect"/>: unsubscribes Core
    /// events, disconnects, and disposes. Safe to call when no Core device is set.
    /// Transports override to also tear down transport-specific state and must call the
    /// base implementation.
    /// </summary>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.CleanupConnection
    protected virtual void CleanupConnection()
    {
        var coreDevice = CoreDevice;
        if (coreDevice == null)
        {
            return;
        }

        UnsubscribeCoreDeviceEvents(coreDevice);

        try
        {
            coreDevice.Disconnect();
        }
        catch (Exception ex)
        {
            AppLogger.Warning(ex, "Error disconnecting Core device during cleanup");
        }

        try
        {
            coreDevice.Dispose();
        }
        catch (Exception ex)
        {
            AppLogger.Warning(ex, "Error disposing Core device during cleanup");
        }

        CoreDevice = null;

        // Release the ErrorOccurred/SendFailed bridge to the Core device just disposed. Without
        // this, a wrapper whose subscriber is still attached keeps the disposed Core device — and
        // through it the transport — reachable for as long as the wrapper is.
        RebindDiagnostics();

        // CoreDevice is now null, so IsConnected reads false. The explicit-disconnect path
        // unsubscribes StatusChanged before cleanup, so notify here to cover teardown (issue #3).
        RaiseIsConnectedChanged();
    }

    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.UnsubscribeCoreDeviceEvents
    private void UnsubscribeCoreDeviceEvents(CoreStreamingDevice coreDevice)
    {
        coreDevice.ChannelsPopulated -= OnCoreChannelsPopulated;
        coreDevice.MessageReceived -= OnCoreMessageReceived;
        coreDevice.StatusChanged -= OnCoreStatusChanged;
    }

    /// <summary>
    /// Handles non-status messages received from Core's DaqifiDevice and routes them
    /// to the protocol handler for streaming data processing.
    /// Status messages are handled via <see cref="OnCoreChannelsPopulated"/>.
    /// </summary>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.OnCoreMessageReceived
    private void OnCoreMessageReceived(object? sender, MessageReceivedEventArgs e)
    {
        HandleInboundMessage(e);
    }

    /// <summary>
    /// Bridges Core's device <c>StatusChanged</c> into an <see cref="IsConnected"/> change
    /// notification. Core maps its transport's status (connect, disconnect, and a transport-detected
    /// drop such as a silent WiFi/TCP link death) onto its <c>Status</c>; <see cref="IsConnected"/>
    /// is a computed property that raises no change on its own, so without this bridge an
    /// IsConnected-derived binding or command would read stale until an unrelated signal (issue #3).
    /// Marshals through <see cref="RaiseIsConnectedChanged"/> because Core raises this from its
    /// transport thread.
    /// <para>
    /// It also clears <see cref="IsStreaming"/> when the connection is lost. Core sets
    /// <c>ConnectionStatus.Lost</c> from its transport's status for an UNEXPECTED drop only — an
    /// intentional <c>Disconnect()</c> is suppressed on Core's side — so this is the authoritative
    /// signal that a stream has died underneath us. Without it the flag stays true forever and the
    /// app goes on claiming to stream from a dead socket (#99): the sample counter freezes while
    /// the UI still reads "Streaming N channel(s)", which is worse than an error because nothing
    /// tells the user to reconnect.
    /// </para>
    /// </summary>
    /// <remarks>
    /// <para>
    /// <b>Which statuses count as a drop.</b> Upstream also treats <c>Disconnected</c> as one.
    /// This port deliberately does not, because at the pinned Core (1.7.0) <c>Disconnected</c> is
    /// reachable only from a caller-issued <c>Disconnect()</c> — <c>DisconnectCore</c> and
    /// <c>MarkDisconnectedWithoutTeardown</c> are the only two producers of it, and both run under
    /// a teardown the app asked for. Every app-initiated teardown path here detaches this handler
    /// (<see cref="Disconnect"/> and <see cref="CleanupConnection"/> both call
    /// <c>UnsubscribeCoreDeviceEvents</c> before touching the Core device), so acting on
    /// <c>Disconnected</c> could only ever re-enter teardown on a device that is already being torn
    /// down. <c>Failed</c> IS included even though it is unreachable today: Core only reports it
    /// when automatic reconnect exhausts its attempts, and this app leaves
    /// <c>DaqifiDevice.ReconnectOptions</c> at its disabled default — so a drop stops at
    /// <c>Lost</c>. Handling it now means enabling reconnect later cannot silently reintroduce the
    /// untorn-down device this method exists to prevent.
    /// </para>
    /// </remarks>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.OnCoreStatusChanged
    protected virtual void OnCoreStatusChanged(object? sender, DeviceStatusEventArgs e)
    {
        if (e.Status is not (ConnectionStatus.Lost or ConnectionStatus.Failed))
        {
            RaiseIsConnectedChanged();
            return;
        }

        OnConnectionLost();

        RaiseIsConnectedChanged();

        var reason = e.Status == ConnectionStatus.Lost ? "connection lost" : "connection failed";
        AppLogger.Instance.Warning($"DAQiFi device {DisplayIdentifier} {reason} unexpectedly.");

        // Raised last, and OUTSIDE the UI-thread marshal, on purpose. The subscriber that matters
        // (ConnectionManager) disposes this device's Core device and its transport, and it does its
        // own marshalling; running that teardown inline on Core's transport thread is what the
        // handler is written for. Raising it after the notifications above also means a subscriber
        // that reads IsConnected/IsStreaming during teardown sees the settled values.
        ConnectionLost?.Invoke(this, new ConnectionLostEventArgs(reason));
    }

    /// <summary>
    /// Raised when Core reports that this device's transport dropped underneath it, rather than
    /// through an app-initiated <see cref="Disconnect"/>. See <see cref="OnCoreStatusChanged"/>
    /// for which Core statuses count.
    /// </summary>
    /// <inheritdoc cref="IDevice.ConnectionLost" />
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.ConnectionLost
    public event EventHandler<ConnectionLostEventArgs>? ConnectionLost;

    /// <summary>
    /// Marks the device as no longer streaming after the transport dropped underneath it.
    /// </summary>
    /// <remarks>
    /// Deliberately does NOT call <see cref="StopStreaming"/>. That sends a stop command down the
    /// very transport that has just died, and on a wedged socket the write can block — this runs on
    /// Core's transport thread, so blocking here stalls Core. The flag and its notification are all
    /// that is needed; the transport is already gone, and teardown belongs to whoever owns the
    /// device lifetime.
    /// </remarks>
    private void OnConnectionLost()
    {
        if (!IsStreaming) { return; }

        IsStreaming = false;

        AppLogger.Instance.Warning(
            $"Connection to {Name} was lost while streaming. The device stopped sending data " +
            "and the stream has been marked inactive.");

        // Same marshalling rationale as RaiseIsConnectedChanged: raised from Core's transport
        // thread, and consumed by bindings.
        RaisePropertyChangedOnUiThread(nameof(IsStreaming));
    }

    /// <summary>
    /// Raises the <see cref="IsConnected"/> change notification on the UI thread.
    /// </summary>
    /// <remarks>
    /// Every producer of this notification can run off the UI thread: Core raises
    /// <c>StatusChanged</c> from its transport thread (including a transport-detected silent drop),
    /// and <see cref="Connect"/> / <see cref="CleanupConnection"/> run on whatever thread drives
    /// connect and teardown. The notification does not stop at a bool — <c>DeviceTileViewModel</c>
    /// re-raises <c>TileBorderBrush</c> off it, which is a <c>Brush</c>, so an unmarshalled raise
    /// pushes UI-valued state to bindings from a worker thread.
    /// <para>
    /// Uses <c>Post</c> rather than <c>Invoke</c>, matching <c>ConnectionManager</c>: it is
    /// non-blocking, so a Core callback is never held while the UI thread catches up, and it cannot
    /// deadlock if the UI thread is itself waiting on Core.
    /// </para>
    /// <para>
    /// Non-throwing, following <c>BootloaderWatcher</c>: during app/dispatcher shutdown <c>Post</c>
    /// can throw, and teardown is exactly when this runs — closing the app disconnects its devices,
    /// so <see cref="CleanupConnection"/> marshals from a Core callback while the dispatcher is
    /// going away. A marshal failure must never propagate into Core's callback or abort teardown;
    /// if the dispatcher is gone there is nothing left bound to update.
    /// </para>
    /// </remarks>
    private void RaiseIsConnectedChanged() => RaisePropertyChangedOnUiThread(nameof(IsConnected));

    /// <summary>
    /// Raises a property-change notification on the UI thread, tolerating a dispatcher that is
    /// shutting down. See <see cref="RaiseIsConnectedChanged"/> for the full rationale — it applies
    /// unchanged to every property raised from a Core transport callback.
    /// </summary>
    private void RaisePropertyChangedOnUiThread(string propertyName)
    {
        if (Dispatcher.UIThread.CheckAccess())
        {
            OnPropertyChanged(propertyName);
            return;
        }

        try
        {
            Dispatcher.UIThread.Post(() => OnPropertyChanged(propertyName));
        }
        catch (Exception)
        {
            // Dispatcher unavailable / shutting down — drop the UI update.
        }
    }
    #endregion

    #region Message Handlers
    /// <summary>
    /// Initializes the protocol handler for automatic message routing.
    /// Uses Core's ProtobufProtocolHandler to route streaming protobuf messages while Core
    /// itself owns status parsing and channel population.
    /// </summary>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.InitializeProtocolHandler
    private void InitializeProtocolHandler()
    {
        _protocolHandler = new ProtobufProtocolHandler(
            statusMessageHandler: OnStatusMessageReceived,
            streamMessageHandler: OnStreamMessageReceived,
            sdCardMessageHandler: _ => { } // SD card messages are text-based, handled separately; empty handler prevents NullReferenceException
        );

        AppLogger.Information("Protocol handler initialized with automatic message routing");
    }

    /// <summary>
    /// Routes incoming messages through the protocol handler.
    /// This method is called by the message consumer for each received message.
    /// </summary>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.OnInboundMessageReceived
    private void OnInboundMessageReceived(object sender, MessageReceivedEventArgs e)
    {
        var inboundMessage = e.Message;

        // Route through protocol handler if available and it can handle this message
        if (_protocolHandler != null && _protocolHandler.CanHandle(inboundMessage))
        {
            // Fire and forget - we don't need to wait for the handler to complete
            _ = _protocolHandler.HandleAsync(inboundMessage);
        }
    }

    /// <summary>
    /// Handles streaming messages received from the device.
    /// Called automatically by ProtobufProtocolHandler when a streaming message is detected.
    /// </summary>
    /// <summary>
    /// Handles status/info messages received from the device (e.g. the <c>SYSTem:SYSInfoPB?</c>
    /// response Core sends during <c>InitializeAsync</c>). Called automatically by
    /// ProtobufProtocolHandler when a status-shaped message is detected.
    /// </summary>
    /// <remarks>
    /// Firmware always includes <c>friendly_device_name</c> in this response — empty when unset —
    /// so it is the authoritative source and is assigned unconditionally (including clearing to
    /// empty). This matters because transport instances like <c>SerialStreamingDevice</c> are
    /// reused across reconnects on the same COM port: without an unconditional overwrite here, a
    /// name left over from a previously connected device (or a name the user just cleared) would
    /// never be cleared, since firmware's fast streaming-frame encoder never re-sends the field at
    /// all (see <see cref="CaptureFriendlyDeviceNameIfPresent"/>).
    /// </remarks>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.OnStatusMessageReceived
    private void OnStatusMessageReceived(DaqifiOutMessage message)
    {
        FriendlyName = message.FriendlyDeviceName ?? string.Empty;
    }

    /// <summary>
    /// Updates <see cref="FriendlyName"/> from a message's <c>friendly_device_name</c> field, but
    /// only when it is non-empty. Firmware's fast streaming-frame encoder
    /// (<c>Nanopb_EncodeStreamingFast</c>) hardcodes only 4 fields (timestamp, analog/digital
    /// data) and never includes <c>friendly_device_name</c> — so on a real Stream message this
    /// field always reads as the proto3 default (empty), and unconditionally assigning it here
    /// would immediately clobber the value <see cref="OnStatusMessageReceived"/> just captured
    /// from the connect-time info response. Kept as a defensive no-op today; would only start
    /// doing something if firmware ever added the field to the streaming encoder.
    /// </summary>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.CaptureFriendlyDeviceNameIfPresent
    private void CaptureFriendlyDeviceNameIfPresent(DaqifiOutMessage message)
    {
        if (!string.IsNullOrEmpty(message.FriendlyDeviceName))
        {
            FriendlyName = message.FriendlyDeviceName;
        }
    }

    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.OnStreamMessageReceived
    private void OnStreamMessageReceived(DaqifiOutMessage message)
    {
        // Belt-and-suspenders: firmware's fast streaming-frame encoder (Nanopb_EncodeStreamingFast)
        // hardcodes only msg_time_stamp/analog_in_data/digital_data/digital_port_dir — it never
        // includes friendly_device_name — so in practice this never fires from a real Stream
        // message. The name arrives via OnStatusMessageReceived instead. Capturing here too is
        // free and correct if firmware ever changes the streaming field set.
        CaptureFriendlyDeviceNameIfPresent(message);

        if (!IsStreaming || Mode != DeviceMode.StreamToApp)
        {
            // Track the counter even while not streaming: the device can emit a final frame
            // after the stop command lands, and the leftover frame at the next start follows
            // it by one sample period — it must be included in the detection reference.
            TrackLastSeenDeviceTimestamp(message.MsgTimeStamp);
            return;
        }

        if (_checkForLeftoverFrames)
        {
            if (IsLeftoverFrameFromPreviousSession(message.MsgTimeStamp))
            {
                TrackLastSeenDeviceTimestamp(message.MsgTimeStamp);
                return;
            }

            _checkForLeftoverFrames = false;
        }

        if (_pendingFirstFrameValidation)
        {
            ValidateFirstFramesWithoutReference(message);
            return;
        }

        ProcessStreamMessage(message);
    }

    /// <summary>
    /// Processes a validated streaming frame: computes its timestamp, updates channel samples,
    /// and dispatches the device message to the logging pipeline.
    /// </summary>
    /// <param name="message">The streaming protobuf message to process.</param>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.ProcessStreamMessage
    private void ProcessStreamMessage(DaqifiOutMessage message)
    {
        TrackLastSeenDeviceTimestamp(message.MsgTimeStamp);

        // Protocol handler already validated this is a streaming message with timestamp
        // No need to revalidate here

        var deviceId = message.DeviceSn.ToString(CultureInfo.InvariantCulture);

        // Apply the device's real streaming-clock frequency to Core's processor once per session, then
        // reconstruct this frame's timestamp — the whole sequence under _timestampProcessorSync so a
        // UI-thread ResetAll (InitializeStreaming / StopStreaming) can neither interleave between the
        // apply and its gate write (which would strand the session on the 50 MHz fallback, issue #39)
        // nor race Core's non-thread-safe processor state. Without the frequency the processor
        // reconstructs against its 20 ns fallback tick (50 MHz) while current firmware runs the timer at
        // 42 MHz, compressing the reconstructed timeline ~16% and drifting without bound (each timestamp
        // is the previous plus elapsed ticks). Applied where the device-id key is known to match the one
        // ProcessTimestamp uses, and re-applied per session because ResetAll() drops per-device
        // frequencies with the baselines.
        DateTime messageTimestamp;
        bool rollover;
        double? firmwareDeltaMs;
        lock (_timestampProcessorSync)
        {
            if (!_timestampFrequencyApplied && TimestampFrequency != 0)
            {
                _timestampProcessor.SetTimestampFrequency(deviceId, TimestampFrequency);
                _timestampFrequencyApplied = true;
            }

            // Use Core's TimestampProcessor for rollover handling
            var timestampResult = _timestampProcessor.ProcessTimestamp(deviceId, message.MsgTimeStamp);
            messageTimestamp = timestampResult.Timestamp;
            rollover = timestampResult.WasRollover;
            // Firmware-measured inter-message delta (immune to TCP jitter); null for the first message.
            firmwareDeltaMs = timestampResult.IsFirstMessage
                ? (double?)null
                : timestampResult.SecondsBetweenMessages * 1000.0;
        }

        var hasDigitalData = message.DigitalData.Length > 0;
        // USB firmware sends pre-scaled floats (AnalogInDataFloat); WiFi sends raw ADC counts (AnalogInData).
        var hasAnalogData = message.AnalogInData.Count > 0 || message.AnalogInDataFloat.Count > 0;

        // Process analog channels - device sends data in channel index order, not activation order
        if (hasAnalogData)
        {
            try
            {
                var activeAnalogChannels = DataChannels.Where(c => c.IsActive && c.Type == ChannelType.Analog)
                                                      .Cast<AnalogChannel>()
                                                      .OrderBy(c => c.Index)
                                                      .ToList();

                // USB firmware sends pre-scaled float values (already in volts); use them directly.
                // WiFi firmware sends raw integer ADC counts; apply channel calibration scaling.
                var hasFloatData = message.AnalogInDataFloat.Count > 0;
                var dataCount = hasFloatData ? message.AnalogInDataFloat.Count : message.AnalogInData.Count;

                for (var dataIndex = 0; dataIndex < dataCount && dataIndex < activeAnalogChannels.Count; dataIndex++)
                {
                    var channel = activeAnalogChannels[dataIndex];
                    double scaledValue;
                    if (hasFloatData)
                    {
                        // Float values are already voltage-scaled by the firmware — no calibration needed
                        scaledValue = message.AnalogInDataFloat[dataIndex];
                    }
                    else
                    {
                        // Raw ADC count — apply channel calibration/scaling via Core
                        scaledValue = channel.GetScaledValue((int)message.AnalogInData[dataIndex]);
                    }

                    // A reading that is not a finite number is not a measurement, and it costs far
                    // more than the one sample it arrived on. Core's per-channel statistics keep a
                    // running ValueSum, so a single NaN makes the Summary flyout's Average read NaN
                    // for the rest of the session while Min and Max keep working — one column of a
                    // row going wrong, which reads as a display bug rather than a bad reading
                    // (issue #295). The plot takes it as a series point and the exporter writes it
                    // out. Refusing it here, at the one place a streamed analog value enters the
                    // app, is what stops it being every consumer's problem to solve separately.
                    //
                    // IsFinite, not IsNaN: an infinity poisons a running sum exactly as thoroughly
                    // and is no more a voltage. That is a different question from the one
                    // SessionSampleWriter answers at the database door, where the constraint is
                    // what SQLite can store — and SQLite stores infinities fine.
                    //
                    // Only the USB float branch above can actually produce one today: Core
                    // sanitizes the calibration coefficients the WiFi branch scales with, so
                    // GetScaledValue cannot return a non-finite value. The guard sits after the
                    // branch anyway because the invariant worth holding is about the value being
                    // published, not about which transport supplied it.
                    if (!double.IsFinite(scaledValue))
                    {
                        ReportNonFiniteReading(channel, scaledValue);
                        continue;
                    }

                    var sample = new DataSample(this, channel, messageTimestamp, scaledValue, firmwareDeltaMs);
                    channel.ActiveSample = sample;
                }

                if (dataCount != activeAnalogChannels.Count)
                {
                    AppLogger.Warning($"[CHANNEL_MAPPING] Analog data count mismatch: received {dataCount} data points for {activeAnalogChannels.Count} active channels");
                }

                // Send debug data if debug mode is enabled
                SendDebugData(message, activeAnalogChannels, messageTimestamp);
            }
            catch (Exception ex)
            {
                ReportStreamProcessingFailure(
                    ref _analogProcessingFailureCount, ex, "[CHANNEL_MAPPING] Error processing analog channel data");
            }
        }

        // Process digital channels. The firmware streams the whole DIO port as a raw pin-state
        // snapshot — bit N is pin N regardless of which channels are enabled, because the
        // wire-level DIO enable is port-global, not per pin — so bits are indexed by channel
        // number, not by position in the active-channel list (issue #663).
        if (hasDigitalData)
        {
            try
            {
                var activeDigitalChannels = DataChannels.Where(c => c.IsActive && c.Type == ChannelType.Digital)
                                                       .OrderBy(c => c.Index)
                                                       .ToList();

                foreach (var channel in activeDigitalChannels)
                {
                    // Output-direction channels display the commanded state, not streamed data
                    if (channel.Direction != ChannelDirection.Input)
                    {
                        continue;
                    }

                    var byteIndex = channel.Index / 8;
                    if (channel.Index < 0 || byteIndex >= message.DigitalData.Length)
                    {
                        continue; // pin beyond the streamed payload: no sample
                    }

                    var bit = (message.DigitalData[byteIndex] & (1 << (channel.Index % 8))) != 0;
                    channel.ActiveSample = new DataSample(
                        this, channel, messageTimestamp, Convert.ToInt32(bit), firmwareDeltaMs);
                }
            }
            catch (Exception ex)
            {
                ReportStreamProcessingFailure(
                    ref _digitalProcessingFailureCount, ex, "Error processing digital channel data");
            }
        }

        var deviceMessage = new DeviceMessage
        {
            DeviceName = Name,
            DeviceSerialNo = message.DeviceSn.ToString(CultureInfo.InvariantCulture),
            DeviceVersion = message.DeviceFwRev,
            TimestampTicks = messageTimestamp.Ticks,
            AppTicks = DateTime.Now.Ticks,
            DeviceStatus = (int)message.DeviceStatus,
            BatteryStatus = (int)message.BattStatus,
            PowerStatus = (int)message.PwrStatus,
            TempStatus = message.TempStatus,
            TargetFrequency = (int)message.TimestampFreq,
            Rollover = rollover,
        };

        DispatchDeviceMessage(deviceMessage);
    }

    /// <summary>
    /// Forwards a parsed streaming frame's device message to the logging pipeline.
    /// Virtual so tests can intercept the dispatch without the application service provider.
    /// </summary>
    /// <param name="deviceMessage">The device message built from the streaming frame.</param>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.DispatchDeviceMessage
    protected virtual void DispatchDeviceMessage(DeviceMessage deviceMessage)
    {
        Logger.LoggingManager.Instance.HandleDeviceMessage(this, deviceMessage);
    }

    /// <summary>
    /// Records the most recent device counter value seen on any stream frame.
    /// </summary>
    /// <param name="deviceTimestamp">The raw 32-bit counter value from the frame.</param>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.TrackLastSeenDeviceTimestamp
    private void TrackLastSeenDeviceTimestamp(uint deviceTimestamp)
    {
        _lastSeenDeviceTimestamp = deviceTimestamp;
        _hasSeenDeviceTimestamp = true;
    }

    /// <summary>
    /// Determines whether a frame received at stream start is a leftover from the previous
    /// streaming session (issue #573). The device's free-running counter is never reset, so a
    /// leftover frame sits within one sample period of the last counter value seen before the
    /// stop, while a genuine new-session frame is offset by the full stop-to-start gap. Modular
    /// uint subtraction keeps the comparison correct across the ~86 s counter wrap.
    /// </summary>
    /// <param name="deviceTimestamp">The raw 32-bit counter value from the frame.</param>
    /// <returns><c>true</c> if the frame belongs to the previous session and must be discarded.</returns>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.IsLeftoverFrameFromPreviousSession
    private bool IsLeftoverFrameFromPreviousSession(uint deviceTimestamp)
    {
        if (!_hasSeenDeviceTimestamp || _discardedLeftoverFrameCount >= MAX_DISCARDED_LEFTOVER_FRAMES)
        {
            return false;
        }

        var timestampFrequency = TimestampFrequency != 0 ? TimestampFrequency : DEFAULT_TIMESTAMP_FREQUENCY;
        var elapsedSeconds = unchecked(deviceTimestamp - _lastSeenDeviceTimestamp) / (double)timestampFrequency;
        if (elapsedSeconds >= STALE_FRAME_WINDOW_SECONDS)
        {
            return false;
        }

        _discardedLeftoverFrameCount++;
        AppLogger.Information(
            $"Discarded leftover frame from previous streaming session at stream start " +
            $"(counter advanced {elapsedSeconds:F4}s, discard {_discardedLeftoverFrameCount} of {MAX_DISCARDED_LEFTOVER_FRAMES} max)");
        return true;
    }

    /// <summary>
    /// Validates the leading frames of a session started without a counter reference (the first
    /// session after connect). The device's leftover frame survives a USB disconnect/reconnect,
    /// so the first frame cannot be trusted on arrival: it is held until the next frame arrives,
    /// and released only when the pair's counter delta fits within one session
    /// (&lt; <see cref="STALE_FRAME_WINDOW_SECONDS"/>). A held frame whose successor implies a
    /// multi-second jump is a leftover from an earlier session and is discarded, the successor
    /// becoming the new held candidate — capped at <see cref="MAX_DISCARDED_LEFTOVER_FRAMES"/>
    /// so genuine data can never be withheld indefinitely. Costs one sample period of latency
    /// on the first sample of the first session only.
    /// </summary>
    /// <param name="message">The streaming frame received while validation is pending.</param>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.ValidateFirstFramesWithoutReference
    private void ValidateFirstFramesWithoutReference(DaqifiOutMessage message)
    {
        var heldFrame = _heldFirstFrame;
        if (heldFrame == null)
        {
            _heldFirstFrame = message;
            TrackLastSeenDeviceTimestamp(message.MsgTimeStamp);
            return;
        }

        var timestampFrequency = TimestampFrequency != 0 ? TimestampFrequency : DEFAULT_TIMESTAMP_FREQUENCY;
        var elapsedSeconds = unchecked(message.MsgTimeStamp - heldFrame.MsgTimeStamp) / (double)timestampFrequency;
        if (elapsedSeconds >= STALE_FRAME_WINDOW_SECONDS
            && _discardedLeftoverFrameCount < MAX_DISCARDED_LEFTOVER_FRAMES)
        {
            _discardedLeftoverFrameCount++;
            AppLogger.Information(
                $"Discarded leftover frame at stream start (no counter reference; counter advanced " +
                $"{elapsedSeconds:F4}s to the next frame, discard {_discardedLeftoverFrameCount} of " +
                $"{MAX_DISCARDED_LEFTOVER_FRAMES} max)");
            _heldFirstFrame = message;
            TrackLastSeenDeviceTimestamp(message.MsgTimeStamp);
            return;
        }

        _pendingFirstFrameValidation = false;
        _heldFirstFrame = null;
        ProcessStreamMessage(heldFrame);
        ProcessStreamMessage(message);
    }

    /// <summary>
    /// Routes a message through the protocol handler for processing.
    /// Called by derived classes (e.g., WiFi devices) that receive messages directly from Core's DaqifiDevice.
    /// </summary>
    /// <param name="e">The message event args containing the protobuf message.</param>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.HandleInboundMessage
    protected void HandleInboundMessage(MessageReceivedEventArgs e)
    {
        OnInboundMessageReceived(this, e);
    }
    #endregion

    #region Streaming Methods
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.SwitchMode
    public void SwitchMode(DeviceMode newMode)
    {
        if (newMode == DeviceMode.LogToDevice && ConnectionType != ConnectionType.Usb)
        {
            throw new InvalidOperationException("SD Card logging is only available when connected via USB");
        }

        if (Mode == newMode)
        {
            return;
        }

        // Stop any current activity
        if (IsStreaming)
        {
            StopStreaming();
        }
        if (IsLoggingToSdCard)
        {
            StopSdCardLogging();
        }

        Mode = newMode;

        // Setup new mode
        switch (Mode)
        {
            case DeviceMode.StreamToApp:
                PrepareLanInterface();
                break;
            case DeviceMode.LogToDevice:
                // Core's StartSdCardLoggingAsync handles the SD interface setup
                // (DisableNetworkLan, EnableStorageSd, SetStreamInterface).
                break;
            default:
                throw new ArgumentOutOfRangeException();
        }

        OnPropertyChanged(nameof(Mode));
    }

    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.StartSdCardLogging
    public void StartSdCardLogging()
    {
        if (ConnectionType != ConnectionType.Usb)
        {
            throw new InvalidOperationException("SD Card logging is only available when connected via USB");
        }

        if (Mode != DeviceMode.LogToDevice)
        {
            throw new InvalidOperationException("Cannot start SD card logging while in StreamToApp mode");
        }

        try
        {
            // Build channel bitmask — Core's StartSdCardLoggingAsync sends EnableAdcChannels
            var analogChannelMask = 0u;
            var hasDigitalChannels = false;

            foreach (var channel in DataChannels.Where(c => c.IsActive))
            {
                if (channel.Type == ChannelType.Analog)
                {
                    analogChannelMask |= 1u << channel.Index;
                }
                else if (channel.Type == ChannelType.Digital)
                {
                    hasDigitalChannels = true;
                }
            }

            // Core doesn't handle DIO enable yet, so desktop still sends this directly
            SendMessage(hasDigitalChannels
                ? ScpiMessageProducer.EnableDioPorts()
                : ScpiMessageProducer.DisableDioPorts());

            var coreDevice = GetConnectedCoreDevice(CoreDeviceForSd);
            // Against the ceiling in force now, not the one in force when the rate was chosen.
            ClampRateToAdvertisedCeiling();
            coreDevice.StreamingFrequency = StreamingFrequency;
            // ...and then under what this channel set can actually sustain, which the ceiling
            // above says nothing about. A start over that cap is refused, not clamped (#272).
            HoldRateToCurrentConfigurationCap(coreDevice);

            // The Core package resumes StartSdCardLoggingAsync continuations on the caller's
            // synchronization context. Running it on the thread pool prevents UI deadlocks.
            var channelMaskString = analogChannelMask.ToString(CultureInfo.InvariantCulture);
            Task.Run(() => coreDevice.StartSdCardLoggingAsync(channelMask: channelMaskString, format: SdCardLogFormat)).GetAwaiter().GetResult();

            IsLoggingToSdCard = coreDevice.IsLoggingToSdCard;
            IsStreaming = true; // We're streaming to SD card
            AppLogger.Information($"Enabled SD card logging for device {DeviceSerialNo}");
            OnPropertyChanged(nameof(IsLoggingToSdCard));
            OnPropertyChanged(nameof(IsStreaming));
        }
        catch (Exception ex)
        {
            AppLogger.Error(ex, $"Failed to enable SD card logging for device {DeviceSerialNo}");
            throw;
        }
    }

    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.StopSdCardLogging
    public void StopSdCardLogging()
    {
        if (ConnectionType != ConnectionType.Usb)
        {
            throw new InvalidOperationException("SD Card logging is only available when connected via USB");
        }

        try
        {
            var coreDevice = GetConnectedCoreDevice(CoreDeviceForSd);
            coreDevice.StopSdCardLoggingAsync().GetAwaiter().GetResult();

            IsLoggingToSdCard = false;
            IsStreaming = false;
            AppLogger.Information($"Disabled SD card logging for device {DeviceSerialNo}");
            OnPropertyChanged(nameof(IsLoggingToSdCard));
            OnPropertyChanged(nameof(IsStreaming));
        }
        catch (Exception ex)
        {
            AppLogger.Error(ex, $"Failed to disable SD card logging for device {DeviceSerialNo}");
            throw;
        }
    }

    /// <summary>
    /// Refreshes the list of SD card log files from the connected device.
    /// </summary>
    /// <remarks>
    /// Transport-agnostic (issue #1): SD file access works over USB and WiFi/TCP alike — the
    /// firmware serves the SD reply on whichever link issued the request. Not gated by connection
    /// type; <see cref="CoreDeviceForSd"/> is null only while disconnected. Whether the connected
    /// device can actually serve SD is Core's call, and it says so with
    /// <see cref="FeatureNotSupportedException"/>.
    /// </remarks>
    /// <exception cref="DeviceNotConnectedException">Thrown when no device is connected.</exception>
    /// <exception cref="SdCardListIncompleteException">
    /// Thrown by Core when the listing did not arrive in full, which is what makes an EMPTY result
    /// here trustworthy: it now means the device answered and had nothing to report, rather than
    /// "the reply may simply never have come". This method used to corroborate every empty listing
    /// with a second round-trip (<c>GetSdCardStorageAsync</c>), because Core's list parser read "no
    /// error lines and no content lines" as an empty directory and so could not tell an unreachable
    /// device from a card with nothing on it — a distinction that stopped being cosmetic once SD
    /// moved onto WiFi (issue #1), where a dead or congested link produces exactly that shape. That
    /// only narrowed the ambiguity, since a later reply says nothing about whether the listing
    /// itself was complete. Core 1.7.0 closed it properly with an end-of-listing terminator
    /// (daqifi-core#396), so the round-trip is gone and this exception is the answer instead;
    /// <see cref="ViewModels.SdCardFailureClassifier"/> reports it as reconnect guidance.
    /// </exception>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.RefreshSdCardFiles
    public void RefreshSdCardFiles()
    {
        EnsureSdOperationsQuiesced();

        var coreDevice = GetConnectedCoreDevice(CoreDeviceForSd);
        var files = Task.Run(() => coreDevice.GetSdCardFilesAsync()).GetAwaiter().GetResult();

        UpdateSdCardFiles(MapSdCardFiles(files));
    }

    /// <summary>
    /// Replaces the current SD card file list and raises a property change notification.
    /// </summary>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.UpdateSdCardFiles
    public void UpdateSdCardFiles(List<SdCardFile> files)
    {
        _sdCardFiles = files;
        OnPropertyChanged(nameof(SdCardFiles));
    }

    /// <summary>
    /// The core device for an operation that requires a live connection, or
    /// <see cref="DeviceNotConnectedException"/> if there is none.
    /// </summary>
    /// <remarks>
    /// "There is no connected device" is an ordinary, expected condition — the user pressed
    /// Disconnect, or unplugged the board — and <see cref="ViewModels.SdCardFailureClassifier"/>
    /// must be able to tell it apart from a defect so it reports a Warning rather than an Error and
    /// a Sentry issue. It used to tell them apart by matching the message as a STRING; Core 1.7.0
    /// gave its own guards <see cref="DeviceNotConnectedException"/> (daqifi-core#395), so throwing
    /// the same type from the app's guards let that matching be deleted outright.
    /// <para>
    /// This is the ONLY guard over the <c>CoreDeviceFor…</c> properties, because a null there has
    /// only ever had one meaning: <see cref="CoreDevice"/> is null, i.e. nothing is connected.
    /// A sibling helper used to throw "Core SD card / live streaming operations are not available
    /// for this device" instead, on the theory that some device type would leave
    /// <see cref="CoreDeviceForSd"/> at its <c>null</c> base default — but every concrete device
    /// (USB, serial, WiFi) overrides it to <see cref="CoreDevice"/>, so that branch was
    /// unreachable and the message it carried was always wrong. Reporting it told a user with a
    /// perfectly capable board that their hardware lacked the feature, and — being untyped — it
    /// reached the classifier's default arm and filed a Sentry issue for pressing Disconnect
    /// (issue #134).
    /// </para>
    /// <para>
    /// A device that genuinely cannot do SD is a real condition, but it is not this one and it is
    /// not decided here: Core merges the connected device's own capability report and throws
    /// <see cref="FeatureNotSupportedException"/>, which the classifier already handles with
    /// firmware-specific guidance. That answer needs a connected device to come from, which is
    /// exactly what this guard has established by the time it returns.
    /// </para>
    /// </remarks>
    private static CoreStreamingDevice GetConnectedCoreDevice(CoreStreamingDevice? coreDevice)
    {
        // Message omitted deliberately: the type's own default is "Device is not connected.",
        // so there is one copy of that sentence and it lives in Core.
        return coreDevice ?? throw new DeviceNotConnectedException();
    }

    /// <summary>
    /// Downloads an SD card log file from the connected device to a local temp path.
    /// </summary>
    /// <param name="fileName">The name of the file on the SD card.</param>
    /// <param name="progress">Optional progress reporter for transfer updates.</param>
    /// <param name="ct">Cancellation token.</param>
    /// <exception cref="InvalidOperationException">Thrown when streaming or SD logging is active.</exception>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.DownloadSdCardFileAsync
    public async Task<SdCardDownloadResult> DownloadSdCardFileAsync(
        string fileName,
        IProgress<SdCardTransferProgress>? progress = null,
        CancellationToken ct = default)
    {
        EnsureSdOperationsQuiesced();

        var coreDevice = GetConnectedCoreDevice(CoreDeviceForSd);
        return await coreDevice.DownloadSdCardFileAsync(fileName, progress, ct);
    }

    /// <summary>
    /// Deletes an SD card log file from the connected device.
    /// </summary>
    /// <param name="fileName">The name of the file to delete.</param>
    /// <param name="ct">Cancellation token.</param>
    /// <exception cref="InvalidOperationException">Thrown when streaming or SD logging is active.</exception>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.DeleteSdCardFileAsync
    public async Task DeleteSdCardFileAsync(string fileName, CancellationToken ct = default)
    {
        EnsureSdOperationsQuiesced();

        var coreDevice = GetConnectedCoreDevice(CoreDeviceForSd);
        await coreDevice.DeleteSdCardFileAsync(fileName, ct);
    }

    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.MapSdCardFiles
    private static List<SdCardFile> MapSdCardFiles(IEnumerable<CoreSdCardFileInfo> files)
    {
        return files.Select(file => new SdCardFile
            {
                FileName = file.FileName,
                CreatedDate = file.CreatedDate ?? DateTime.MinValue
            })
            .Where(file => IsImportableSdLogFileName(file.FileName))
            .ToList();
    }

    /// <summary>
    /// Refuses an SD card file operation while the device is busy streaming or logging to its card.
    /// </summary>
    /// <remarks>
    /// Throws <see cref="SdOperationBlockedException"/> rather than a bare
    /// <see cref="InvalidOperationException"/> so
    /// <see cref="ViewModels.SdCardFailureClassifier"/> can recognise this for what it is. Being
    /// busy is an ordinary condition with an obvious remedy, but untyped it reached the
    /// classifier's default arm and was reported as an app defect — an Error and a Sentry issue,
    /// advising the user to check a connection that was never the problem (issue #146). The new
    /// type still derives from <see cref="InvalidOperationException"/>, so the exception contract
    /// documented on the three guarded operations is unchanged.
    /// </remarks>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.EnsureSdOperationsQuiesced
    private void EnsureSdOperationsQuiesced()
    {
        if (IsLoggingToSdCard)
        {
            throw new SdOperationBlockedException(SdOperationBlockedReason.SdCardLogging);
        }

        if (IsStreaming)
        {
            throw new SdOperationBlockedException(SdOperationBlockedReason.Streaming);
        }
    }

    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.IsImportableSdLogFileName
    private static bool IsImportableSdLogFileName(string fileName)
    {
        if (string.IsNullOrWhiteSpace(fileName))
        {
            return false;
        }

        var extension = Path.GetExtension(fileName);
        return extension.Equals(".bin", StringComparison.OrdinalIgnoreCase)
            || extension.Equals(".json", StringComparison.OrdinalIgnoreCase)
            || extension.Equals(".csv", StringComparison.OrdinalIgnoreCase);
    }

    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.InitializeStreaming
    public void InitializeStreaming()
    {
        if (IsStreaming) return;

        // Prevent computer sleep when starting streaming. The P/Invoke
        // targets kernel32.dll — a DllNotFoundException on mobile — so it
        // is Windows-guarded; other heads skip the block entirely and log
        // nothing. Mobile sleep-prevention (a wake lock) is a future
        // divergence, not required to stream.
        if (OperatingSystem.IsWindows())
        {
            var previousState = NativeMethods.SetThreadExecutionState(NativeMethods.EsContinuous | NativeMethods.EsSystemRequired);
            if (previousState == 0) // Check for failure (returns 0 on failure)
            {
                AppLogger.Warning("Failed to set computer from sleeping while streaming.");
            }
            else
            {
                AppLogger.Information("Preventing computer sleep during streaming.");
            }
        }

        if (Mode != DeviceMode.StreamToApp)
        {
            throw new InvalidOperationException("Cannot initialize streaming while in LogToDevice mode");
        }

        var coreStreamingDevice = GetConnectedCoreDevice(CoreDeviceForStreaming);
        // Against the ceiling in force now, not the one in force when the rate was chosen.
        ClampRateToAdvertisedCeiling();
        coreStreamingDevice.StreamingFrequency = StreamingFrequency;
        // ...and then under what this channel set can actually sustain, which the ceiling above
        // says nothing about. A start over that cap is refused, not clamped, and the session
        // produces no samples at all (#272). Runs before StartStreaming below: the document read
        // is a text exchange and must not overlap the stream.
        HoldRateToCurrentConfigurationCap(coreStreamingDevice);

        // A session must never anchor its time axis on prior-session data (issue #573).
        // Reset the timestamp baseline here — StopStreaming's reset is skipped on unplug and
        // error paths — and arm leftover-frame detection: the device holds the final frame of
        // the previous session in its transmit path and emits it first when streaming resumes.
        // With a counter reference (any frame seen on this connection), leftovers are recognized
        // directly; without one (first session after connect — the device's leftover survives a
        // disconnect/reconnect), the first frame is held and validated against its successor.
        lock (_timestampProcessorSync)
        {
            _timestampProcessor.ResetAll();
            _timestampFrequencyApplied = false;
        }
        _discardedLeftoverFrameCount = 0;
        // Interlocked, because a 64-bit assignment is not guaranteed atomic on a 32-bit
        // runtime and these are written here while a stream handler may still be incrementing.
        Interlocked.Exchange(ref _analogProcessingFailureCount, 0);
        Interlocked.Exchange(ref _digitalProcessingFailureCount, 0);
        Interlocked.Exchange(ref _debugDataFailureCount, 0);
        _nonFiniteReadingCounts.Clear();
        _checkForLeftoverFrames = _hasSeenDeviceTimestamp;
        _pendingFirstFrameValidation = !_hasSeenDeviceTimestamp;
        _heldFirstFrame = null;

        coreStreamingDevice.StartStreaming();
        IsStreaming = coreStreamingDevice.IsStreaming;
        AppLogger.AddBreadcrumb("streaming", $"Streaming started at {StreamingFrequency} Hz");
    }

    /// <summary>
    /// Reports a failure raised inside a per-message path, which runs once per streamed message
    /// and so cannot report every occurrence.
    /// </summary>
    /// <remarks>
    /// All three call sites previously did <c>AppLogger.Error($"...: {ex.Message}")</c>, which
    /// was wrong twice over.
    /// <list type="number">
    ///   <item><description>
    ///     It passed only <c>ex.Message</c>, so the exception object — type, stack trace, inner
    ///     exception — was discarded at the one place it was needed. What reached Sentry was a
    ///     sentence, and the attached stack trace pointed at the catch block, which is the same
    ///     for every possible decode fault. Passing <c>ex</c> means the report names the step
    ///     that actually threw.
    ///   </description></item>
    ///   <item><description>
    ///     It reported unconditionally from a per-message handler. A persistent fault — a
    ///     payload shape the decode does not expect, a channel list that no longer matches the
    ///     stream — therefore raises one event per message. At the 1 kHz this app streams at,
    ///     that is a thousand events a second: it buries every other issue in the project and
    ///     spends the quota that would have carried them.
    ///   </description></item>
    /// </list>
    /// <para>
    /// So Sentry gets the 1st, 10th, 100th… occurrence, with the full exception and the running
    /// count in the message. Powers of ten because the facts worth an event are "it happened at
    /// all" and "it is still happening two orders of magnitude later"; every occurrence in
    /// between is the same event again. The count travels in the message, so a single report
    /// still says how bad it is — which a suppressed-and-forgotten scheme cannot.
    /// </para>
    /// <para>
    /// The occurrences in between are not all logged locally either, and the reason is the same
    /// arithmetic one level down. <see cref="AppLogger.Warning(Exception, string)"/> raises no
    /// Sentry event, but it does write the log file and leave a breadcrumb, and the breadcrumb
    /// ring is bounded (SDK default 100) — so logging every occurrence of a 1 kHz fault would
    /// flush the ring ten times a second and throw away the connect / streaming-start trail that
    /// makes the eventual report readable, plus turn the log file into a write storm that rolls
    /// its own archives away. The first <see cref="FullyLoggedFailureCount"/> occurrences are
    /// logged in full, which covers a transient fault completely; past that only the reported
    /// ones are, and the count in the next report is what conveys the true frequency.
    /// </para>
    /// <para>
    /// The per-session reset races, and that is accepted rather than overlooked. Messages are
    /// dispatched fire-and-forget (see OnInboundMessageReceived), so a handler already past the
    /// IsStreaming guard when a restart resets the counters can increment afterwards, numbering
    /// a stale failure as occurrence 1 or pushing the session's real first failure to 2 — where
    /// it is logged locally but not sent until occurrence 10. Closing it properly needs a
    /// stream generation threaded through every dispatched message and checked before
    /// reporting: real work in the per-message path, to make a log line's ordinal exact. The
    /// counters gate only when to log, never device behaviour or data, and the neighbouring
    /// _discardedLeftoverFrameCount — which does gate behaviour — is reset the same way.
    /// </para>
    /// </remarks>
    private void ReportStreamProcessingFailure(ref long failureCount, Exception ex, string what)
    {
        var occurrence = Interlocked.Increment(ref failureCount);
        var message = $"{what} (occurrence {occurrence.ToString(CultureInfo.InvariantCulture)})";

        if (IsPowerOfTen(occurrence))
        {
            AppLogger.Error(ex, message);
        }
        else if (occurrence < FullyLoggedFailureCount)
        {
            // Local log and breadcrumb only — Warning deliberately does not capture to Sentry.
            AppLogger.Warning(ex, message);
        }

        // Otherwise silent: the next power-of-ten report carries the count.
    }

    /// <summary>
    /// How many occurrences of a per-message decode failure are logged in full before the
    /// report thins out to powers of ten. Ten is enough to capture a transient fault end to
    /// end while staying a small fraction of the bounded breadcrumb ring.
    /// </summary>
    private const int FullyLoggedFailureCount = 10;

    /// <summary>
    /// Reports a reading refused by <see cref="ProcessStreamMessage"/> for not being a finite
    /// number, throttled the way every other per-message report in this class is.
    /// </summary>
    /// <remarks>
    /// <para>
    /// Counted <b>per channel</b>, not once for the device, and that is the difference between a
    /// diagnosis and a misleading silence: a board that starts emitting NaN on a second channel an
    /// hour into a run would say nothing at all if the first channel had already pushed a shared
    /// count past the next power of ten. Every channel gets its own occurrence 1.
    /// </para>
    /// <para>
    /// Only powers of ten are logged. A channel whose every reading is bad produces one per
    /// decade of samples — enough that it keeps announcing itself, few enough that it cannot flush
    /// the bounded Sentry breadcrumb ring or turn the log into a write storm, which is the same
    /// arithmetic <see cref="ReportStreamProcessingFailure"/> documents at length.
    /// </para>
    /// <para>
    /// <b>There is no UI surface for this</b>, and that is a deliberate limit rather than an
    /// oversight: it is a warning in the log plus a Sentry breadcrumb, the same answer
    /// <c>SessionSampleWriter</c> gives for the rows it refuses. Raising it to the notification
    /// bell means crossing <c>LoggingManager</c> and <c>DaqifiViewModel</c> and is a separate
    /// decision. What the user sees without reading a log is the absence of the symptom — the
    /// Average stays a number, and a channel whose readings are unusable stops updating rather
    /// than showing NaN.
    /// </para>
    /// </remarks>
    private void ReportNonFiniteReading(AnalogChannel channel, double value)
    {
        var occurrence = _nonFiniteReadingCounts.AddOrUpdate(
            channel.Index, 1L, static (_, previous) => previous + 1);

        if (!IsPowerOfTen(occurrence))
        {
            // Silent: the next power-of-ten report carries the count.
            return;
        }

        // Invariant formatting for the value, so a NaN or an infinity is written the way it is
        // searched for regardless of the machine's locale.
        AppLogger.Warning(
            $"Discarded a non-finite reading ({value.ToString("R", CultureInfo.InvariantCulture)}) from " +
            $"channel {channel.Name} on {Name}: it is not a measurement and would corrupt this " +
            $"channel's statistics for the rest of the session. " +
            $"{occurrence.ToString(CultureInfo.InvariantCulture)} discarded on this channel so far " +
            $"this session.");
    }

    /// <summary>
    /// How many non-finite readings this device has discarded on the analog channel with
    /// <paramref name="channelIndex"/> since streaming last started.
    /// </summary>
    /// <remarks>
    /// Visible to <c>Daqifi.Avalonia.Tests</c> only, via InternalsVisibleTo in
    /// Daqifi.Avalonia.csproj. It is the tally <see cref="ReportNonFiniteReading"/> draws its
    /// occurrence number from, and the only way to pin that the tally is kept per channel rather
    /// than per device — <see cref="AppLogger"/> is a singleton that discards its NLog logger in
    /// test mode, so the warning line itself cannot be asserted on.
    /// </remarks>
    internal long DiscardedNonFiniteReadings(int channelIndex) =>
        _nonFiniteReadingCounts.TryGetValue(channelIndex, out var count) ? count : 0;

    /// <summary>Whether <paramref name="value"/> is 1, 10, 100, 1000, …</summary>
    private static bool IsPowerOfTen(long value)
    {
        if (value < 1) { return false; }

        while (value % 10 == 0) { value /= 10; }

        return value == 1;
    }

    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.StopStreaming
    public void StopStreaming()
    {
        if (!IsStreaming) return;

        // Allow computer sleep again when stopping streaming (Windows-only
        // P/Invoke — see InitializeStreaming).
        if (OperatingSystem.IsWindows())
        {
            var previousState = NativeMethods.SetThreadExecutionState(NativeMethods.EsContinuous);
            if (previousState == 0) // Check for failure
            {
                AppLogger.Warning("Failed to reset thread execution state to allow sleep.");
            }
            else
            {
                AppLogger.Information("Allowing computer sleep after streaming.");
            }
        }

        var coreStreamingDevice = GetConnectedCoreDevice(CoreDeviceForStreaming);
        coreStreamingDevice.StopStreaming();
        IsStreaming = coreStreamingDevice.IsStreaming;
        AppLogger.AddBreadcrumb("streaming", "Streaming stopped");

        // Reset timestamp processor state for clean restart
        lock (_timestampProcessorSync)
        {
            _timestampProcessor.ResetAll();
            _timestampFrequencyApplied = false;
        }

        foreach (var channel in DataChannels)
        {
            if (channel.ActiveSample != null)
            {
                channel.ActiveSample = null;
            }
        }
    }

    #endregion

    #region Channel Methods
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.AddChannel
    public void AddChannel(IChannel channelToAdd)
    {
        var channel = DataChannels.FirstOrDefault(c => Equals(c, channelToAdd));
        if (channel == null)
        {
            AppLogger.Error($"There was a problem adding channel: {channelToAdd.Name}.  " +
                            $"Trying to add a channel that does not belong to the device: {Name}");
            return;
        }

        switch (channel.Type)
        {
            case ChannelType.Analog:
                var activeAnalogChannels = GetActiveAnalogChannels();
                var channelSetByte = 0u; // Use unsigned int to handle higher channel numbers

                // Get Exsiting Channel Set Byte
                foreach (var activeChannel in activeAnalogChannels)
                {
                    channelSetByte = channelSetByte | (1u << activeChannel.Index);
                }

                // Add Channel Bit to the Channel Set Byte
                channelSetByte = channelSetByte | (1u << channel.Index);

                // Convert to a string
                var channelSetString = Convert.ToString(channelSetByte);

                // Send the command to add the channel
                SendMessage(ScpiMessageProducer.EnableAdcChannels(channelSetString));
                break;
            case ChannelType.Digital:
                SendMessage(ScpiMessageProducer.EnableDioPorts());
                break;
        }

        channel.IsActive = true;
    }

    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.RemoveChannel
    public void RemoveChannel(IChannel channelToRemove)
    {
        switch (channelToRemove.Type)
        {
            case ChannelType.Analog:
                var activeAnalogChannels = GetActiveAnalogChannels();
                var channelSetByte = 0u; // Use unsigned int to handle higher channel numbers

                //Get Exsiting Channel Set Byte
                foreach (var activeChannel in activeAnalogChannels)
                {
                    channelSetByte = channelSetByte | (1u << activeChannel.Index);
                }

                //Remove Channel Bit from the Channel Set Byte
                channelSetByte = channelSetByte & ~(1u << channelToRemove.Index);

                //Convert to a string
                var channelSetString = Convert.ToString(channelSetByte);

                //Send the command to remove the channel
                SendMessage(ScpiMessageProducer.EnableAdcChannels(channelSetString));
                break;
        }

        var channel = DataChannels.FirstOrDefault(c => Equals(c, channelToRemove));
        if (channel == null)
        {
            AppLogger.Error($"There was a problem removing channel: {channelToRemove.Name}");
        }
        else
        {
            channel.IsActive = false;
        }
    }

    /// <summary>
    /// Enables multiple channels on the device with a single SCPI command per channel type.
    /// </summary>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.AddChannels
    public void AddChannels(IEnumerable<IChannel> channelsToAdd)
    {
        var channelSetByte = 0u;
        var hasAnalog = false;
        var hasDigital = false;

        foreach (var channelToAdd in channelsToAdd)
        {
            var channel = DataChannels.FirstOrDefault(c => Equals(c, channelToAdd));
            if (channel == null) continue;

            switch (channel.Type)
            {
                case ChannelType.Analog:
                    channelSetByte |= (1u << channel.Index);
                    channel.IsActive = true;
                    hasAnalog = true;
                    break;
                case ChannelType.Digital:
                    channel.IsActive = true;
                    hasDigital = true;
                    break;
            }
        }

        if (hasAnalog)
        {
            SendMessage(ScpiMessageProducer.EnableAdcChannels(Convert.ToString(channelSetByte)));
        }
        if (hasDigital)
        {
            SendMessage(ScpiMessageProducer.EnableDioPorts());
        }
    }

    /// <summary>
    /// Sets and persists a user-defined friendly name to the device's NVM.
    /// </summary>
    /// <remarks>
    /// No producer helper exists in <c>Daqifi.Core.Communication.Producers.ScpiMessageProducer</c>
    /// for this firmware command yet, so the SCPI text is built directly here (mirrors the
    /// quoted-string pattern <c>ScpiMessageProducer</c> already uses for SSID/password).
    /// Commands: <c>SYSTem:DEVice:NAME "name"</c> then <c>SYSTem:DEVice:NAME:SAVE</c>.
    /// </remarks>
    /// <param name="name">
    /// 1-31 printable ASCII characters (0x20-0x7E); cannot contain <c>"</c> or <c>\</c> — matches
    /// firmware's <c>daqifi_settings_FriendlyNameIsValid</c> validation exactly, so a name that
    /// passes here will not be rejected by the device.
    /// </param>
    /// <exception cref="ArgumentException">Thrown when <paramref name="name"/> fails validation.</exception>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.SetFriendlyName
    public void SetFriendlyName(string name)
    {
        ArgumentNullException.ThrowIfNull(name);
        if (!IsFriendlyNameValid(name))
        {
            throw new ArgumentException(
                "Device name must be 1-31 printable ASCII characters and cannot contain '\"' or '\\'.",
                nameof(name));
        }

        if (CoreDevice is not { IsConnected: true })
        {
            AppLogger.Warning($"Ignored SetFriendlyName for device {DeviceDisplayName}: device is not connected.");
            return;
        }

        SendMessage(new ScpiMessage($"SYSTem:DEVice:NAME \"{name}\""));
        SendMessage(new ScpiMessage("SYSTem:DEVice:NAME:SAVE"));

        // Optimistic local update: the device does not echo the new name back synchronously,
        // and it may not stream another status frame for a while (e.g. StreamToApp is idle).
        FriendlyName = name;
    }

    /// <summary>
    /// Validates a candidate friendly name against firmware's acceptance rule: printable ASCII
    /// (0x20-0x7E) only, excluding <c>"</c> and <c>\</c> (which would break the SCPI string
    /// literal and the JSON info-message encoding), within <see cref="MAX_FRIENDLY_NAME_LENGTH"/>.
    /// </summary>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.IsFriendlyNameValid
    private static bool IsFriendlyNameValid(string name)
    {
        if (name.Length is 0 or > MAX_FRIENDLY_NAME_LENGTH)
        {
            return false;
        }

        foreach (var c in name)
        {
            if (c is < (char)0x20 or > (char)0x7E or '"' or '\\')
            {
                return false;
            }
        }

        return true;
    }

    /// <summary>
    /// Disables all channels on the device.
    /// </summary>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.RemoveAllChannels
    public void RemoveAllChannels()
    {
        SendMessage(ScpiMessageProducer.EnableAdcChannels("0"));
        SendMessage(ScpiMessageProducer.DisableDioPorts());
        foreach (var channel in DataChannels)
        {
            channel.IsActive = false;
        }
    }

    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.GetActiveAnalogChannels
    private IEnumerable<IChannel> GetActiveAnalogChannels()
    {
        return DataChannels.Where(channel => channel.Type == ChannelType.Analog && channel.IsActive).ToList();
    }

    /// <inheritdoc />
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.SetChannelOutputValue
    public void SetChannelOutputValue(IChannel channel, double value)
    {
        if (channel.Type != ChannelType.Digital)
        {
            return;
        }

        ExecuteDioCommand(channel, "drive output",
            (coreDevice, coreChannel) => coreDevice.SetDioValue(coreChannel, value >= 0.5));
    }

    /// <inheritdoc />
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.SetChannelDirection
    public void SetChannelDirection(IChannel channel, ChannelDirection direction)
    {
        if (channel.Type != ChannelType.Digital)
        {
            return;
        }

        ExecuteDioCommand(channel, "set direction",
            (coreDevice, coreChannel) => coreDevice.SetDioDirection(coreChannel, direction));
    }

    /// <inheritdoc />
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.SetChannelPwmEnabled
    public void SetChannelPwmEnabled(IChannel channel, bool enabled)
    {
        if (channel.Type != ChannelType.Digital)
        {
            return;
        }

        var dutyCyclePercent = channel.PwmDutyCyclePercent;
        var frequencyHz = PwmFrequencyHz;

        ExecuteDioCommand(channel, enabled ? "enable PWM" : "disable PWM", (coreDevice, coreChannel) =>
        {
            if (enabled)
            {
                // Core-documented call order: duty, then the shared frequency, then enable
                // (issue #664). Duty and frequency are resent on every enable so the device
                // runs exactly what the UI shows — a device keeps its PWM state across host
                // disconnects, so the session bookkeeping alone cannot be trusted.
                coreDevice.SetPwmDutyCycle(coreChannel, dutyCyclePercent);
                coreDevice.SetPwmFrequency(frequencyHz);
                coreDevice.SetPwmEnabled(coreChannel, true);
            }
            else
            {
                coreDevice.SetPwmEnabled(coreChannel, false);
            }
        });
    }

    /// <inheritdoc />
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.SetChannelPwmDutyCycle
    public void SetChannelPwmDutyCycle(IChannel channel, int dutyCyclePercent)
    {
        if (channel.Type != ChannelType.Digital)
        {
            return;
        }

        ExecuteDioCommand(channel, "set PWM duty cycle",
            (coreDevice, coreChannel) => coreDevice.SetPwmDutyCycle(coreChannel, dutyCyclePercent));
    }

    /// <inheritdoc />
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.PwmFrequencyHz
    public int PwmFrequencyHz
    {
        get => _pwmFrequencyHz;
        set
        {
            var clamped = Math.Clamp(
                value, CoreStreamingDevice.MinPwmFrequencyHz, CoreStreamingDevice.MaxPwmFrequencyHz);
            if (_pwmFrequencyHz != clamped)
            {
                _pwmFrequencyHz = clamped;
                ExecuteDeviceCommand("set PWM frequency",
                    coreDevice => coreDevice.SetPwmFrequency(clamped));
            }

            // Always notify so an out-of-range edit snaps the bound control back.
            OnPropertyChanged();
        }
    }

    /// <summary>
    /// Runs a Core DIO command against the wrapped Core channel, with the same
    /// log-and-no-op-when-unavailable semantics as <see cref="ExecuteDeviceCommand"/>.
    /// </summary>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.ExecuteDioCommand
    private void ExecuteDioCommand(
        IChannel channel,
        string operation,
        Action<CoreStreamingDevice, Daqifi.Core.Channel.IChannel> command)
    {
        if (channel is not DigitalChannel digitalChannel)
        {
            AppLogger.Warning($"Ignored {operation} for {channel.Name}: not a digital channel wrapper.");
            return;
        }

        ExecuteDeviceCommand(operation, $"digital channel {channel.Name}",
            coreDevice => command(coreDevice, digitalChannel.CoreChannel));
    }

    /// <summary>
    /// Runs a Core device command. Core throws when the device is disconnected, but these
    /// calls originate from UI property setters that can race a disconnect — so
    /// unavailability is logged and swallowed to preserve the pre-delegation no-op
    /// semantics instead of surfacing an exception through a WPF binding.
    /// </summary>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.ExecuteDeviceCommand
    private void ExecuteDeviceCommand(string operation, string target, Action<CoreStreamingDevice> command)
    {
        var coreDevice = CoreDevice;
        if (coreDevice == null || !coreDevice.IsConnected)
        {
            AppLogger.Warning($"Ignored {operation} for {target}: device is not connected.");
            return;
        }

        try
        {
            command(coreDevice);
        }
        catch (Exception ex)
        {
            AppLogger.Error(ex, $"Failed to {operation} for {target}");
        }
    }

    /// <summary>
    /// Runs a device-level Core command (no channel involved), logging against this
    /// device's display name.
    /// </summary>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.ExecuteDeviceCommand
    private void ExecuteDeviceCommand(string operation, Action<CoreStreamingDevice> command)
    {
        ExecuteDeviceCommand(operation, $"device {DeviceDisplayName}", command);
    }

    /// <summary>
    /// Handles the <see cref="DaqifiDevice.ChannelsPopulated"/> event from Core.
    /// Syncs metadata and channel wrappers from the already-populated Core device.
    /// Virtual so transports can layer additional signaling (serial signals its
    /// initial-status wait) before the shared sync runs.
    /// </summary>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.OnCoreChannelsPopulated
    protected virtual void OnCoreChannelsPopulated(object? sender, ChannelsPopulatedEventArgs e)
    {
        if (sender is not DaqifiDevice coreDevice)
        {
            return;
        }

        SyncFromCoreDevice(coreDevice);
    }

    /// <summary>
    /// Applies the current Core device metadata and channel state to the desktop wrapper.
    /// Core remains the source of truth for status parsing and channel creation; desktop keeps
    /// its richer channel objects for WPF-only concerns.
    /// </summary>
    /// <param name="coreDevice">The already-populated Core device.</param>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.SyncFromCoreDevice
    protected void SyncFromCoreDevice(DaqifiDevice coreDevice)
    {
        ArgumentNullException.ThrowIfNull(coreDevice);

        try
        {
            HydrateDeviceMetadata(coreDevice.Metadata);
            SyncChannelsFromCore(coreDevice.Channels);
            DeviceState = coreDevice.State;

            AppLogger.Information(
                $"Synchronized {coreDevice.Channels.Count} channels from Core " +
                $"({coreDevice.Channels.Count(c => c.Type == ChannelType.Analog)} analog, " +
                $"{coreDevice.Channels.Count(c => c.Type == ChannelType.Digital)} digital)");
        }
        catch (Exception ex)
        {
            AppLogger.Error(ex, $"Failed to synchronize Core device state for {DisplayIdentifier}");
            throw;
        }
    }

    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.SyncChannelsFromCore
    private void SyncChannelsFromCore(IReadOnlyList<Daqifi.Core.Channel.IChannel> coreChannels)
    {
        var existingChannels = DataChannels.ToDictionary(GetChannelKey);
        var updatedChannels = new List<IChannel>(coreChannels.Count);

        foreach (var coreChannel in coreChannels)
        {
            var channelKey = GetChannelKey(coreChannel);

            if (existingChannels.TryGetValue(channelKey, out var existingChannel))
            {
                switch (existingChannel)
                {
                    case AnalogChannel desktopAnalogChannel
                        when coreChannel is Daqifi.Core.Channel.IAnalogChannel coreAnalogChannel:
                        desktopAnalogChannel.ReplaceCoreChannel(coreAnalogChannel);
                        desktopAnalogChannel.DeviceName = DevicePartNumber;
                        desktopAnalogChannel.DeviceSerialNo = DeviceSerialNo;
                        updatedChannels.Add(desktopAnalogChannel);
                        continue;

                    case DigitalChannel desktopDigitalChannel
                        when coreChannel is Daqifi.Core.Channel.IDigitalChannel coreDigitalChannel:
                        desktopDigitalChannel.ReplaceCoreChannel(coreDigitalChannel);
                        desktopDigitalChannel.DeviceName = DevicePartNumber;
                        desktopDigitalChannel.DeviceSerialNo = DeviceSerialNo;
                        updatedChannels.Add(desktopDigitalChannel);
                        continue;
                }
            }

            var desktopChannel = CreateDesktopChannel(coreChannel);
            if (desktopChannel != null)
            {
                updatedChannels.Add(desktopChannel);
            }
        }

        DataChannels.Clear();
        DataChannels.AddRange(updatedChannels);
    }

    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.CreateDesktopChannel
    private IChannel? CreateDesktopChannel(Daqifi.Core.Channel.IChannel coreChannel)
    {
        return coreChannel switch
        {
            Daqifi.Core.Channel.IAnalogChannel coreAnalogChannel => new AnalogChannel(this, coreAnalogChannel),
            Daqifi.Core.Channel.IDigitalChannel coreDigitalChannel => new DigitalChannel(this, coreDigitalChannel),
            _ => null
        };
    }

    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.GetChannelKey
    private static string GetChannelKey(IChannel channel)
    {
        return $"{channel.Type}:{channel.Index}";
    }

    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.GetChannelKey
    private static string GetChannelKey(Daqifi.Core.Channel.IChannel channel)
    {
        return $"{channel.Type}:{channel.ChannelNumber}";
    }

    /// <summary>
    /// Copies Core's device description onto this wrapper's <see cref="Metadata"/> and raises the
    /// bindings that read through it.
    /// </summary>
    /// <remarks>
    /// The copy itself is <see cref="DeviceMetadata.CopyFrom"/> — Core's own, because a field-by-
    /// field copy written here cannot stay correct. Two of the fields
    /// (<c>CapabilityDocument</c> and the board the capabilities were derived from) have no public
    /// setter, so an external copy cannot reach them at all; and the hand-written one this replaces
    /// had already fallen behind on three more it could reach
    /// (<see cref="DeviceCapabilities.HasWincWifiModule"/>, <c>FriendlyName</c> and <c>Health</c>),
    /// each of which was silently dropped on every hydrate.
    /// </remarks>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.HydrateDeviceMetadata
    private void HydrateDeviceMetadata(DeviceMetadata coreMetadata)
    {
        ArgumentNullException.ThrowIfNull(coreMetadata);

        Metadata.CopyFrom(coreMetadata);

        // DeviceType is an [ObservableProperty] and not backed by Metadata, so set it explicitly.
        DeviceType = Metadata.DeviceType;

        // All other identity properties delegate directly to Metadata — just notify bindings.
        OnPropertyChanged(nameof(DevicePartNumber));
        OnPropertyChanged(nameof(DeviceSerialNo));
        OnPropertyChanged(nameof(DeviceVersion));
        OnPropertyChanged(nameof(IpAddress));
        OnPropertyChanged(nameof(MacAddress));
        OnPropertyChanged(nameof(DisplayIdentifier));

        // HasWincWifiModule reads Metadata.Capabilities, which is replaced above. DeviceType's
        // generated setter also notifies it, but only when the board's *value* changes — a
        // re-derived capability set on an unchanged board would otherwise go unannounced.
        OnPropertyChanged(nameof(HasWincWifiModule));

        // Capabilities was replaced above, so the ceiling the stored rate was clamped against may
        // just have moved.
        ClampRateToAdvertisedCeiling();

        if (!string.IsNullOrWhiteSpace(Metadata.Ssid))
        {
            NetworkConfiguration.Ssid = Metadata.Ssid;
        }

        // Security type 0 is the open-network case and should not be filtered out.
        NetworkConfiguration.SecurityType = (WifiSecurityType)Metadata.WifiSecurityMode;

        if (Metadata.WifiInfrastructureMode > 0)
        {
            NetworkConfiguration.Mode = (WifiMode)Metadata.WifiInfrastructureMode;
        }

        AppLogger.Information($"Detected device type: {DeviceType} from part number: {Metadata.PartNumber}");
    }

    #endregion

    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.InitializeDeviceState
    public void InitializeDeviceState()
    {
        // Initialize protocol handler for automatic message routing
        InitializeProtocolHandler();
    }

    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.UpdateNetworkConfiguration
    public async Task UpdateNetworkConfiguration()
    {
        var coreDevice = GetConnectedCoreDevice(CoreDeviceForNetworkConfiguration);

        var restoreSdInterface = ConnectionType == ConnectionType.Usb && Mode == DeviceMode.LogToDevice;

        if (IsStreaming)
        {
            StopStreaming();
        }

        try
        {
            await coreDevice.UpdateNetworkConfigurationAsync(NetworkConfiguration);
        }
        finally
        {
            // Core always restores LAN after applying settings. USB devices that are currently
            // logging to the SD card need the desktop wrapper to switch the shared SPI bus back,
            // even if the Core update fails after toggling the shared SPI bus to LAN.
            //
            // This restore is best-effort: PrepareSdInterface delegates to the Core device and
            // throws when it is gone (e.g. a mid-update disconnect nulls CoreDevice). Inside a
            // finally that would mask the original UpdateNetworkConfigurationAsync failure, so
            // swallow-and-log here — the SPI bus is moot once the device is disconnected anyway.
            if (restoreSdInterface)
            {
                try
                {
                    PrepareSdInterface();
                }
                catch (Exception restoreException)
                {
                    AppLogger.Warning(
                        restoreException,
                        "Failed to restore the SD interface for device " +
                        $"{DeviceSerialNo} after a network configuration update.");
                }
            }
        }
    }

    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.Reboot
    public void Reboot()
    {
        SendMessage(ScpiMessageProducer.RebootDevice);
        Disconnect();
    }

    /// <summary>
    /// Powers the device's acquisition subsystem on. Idempotent: the device accepts it in any
    /// state, and Core sends the same command during a connect that initializes the device.
    /// </summary>
    /// <remarks>
    /// Callers need this when the device was connected with Core's <c>InitializeDevice=false</c>,
    /// which skips the power-on step — a board that associated but never powered its analog
    /// front-end reports itself streaming and delivers no samples.
    /// <para>
    /// Goes through <see cref="SendMessage"/> like every other command this class sends, so the
    /// command text and its line terminator stay inside the device layer with the rest of the
    /// SCPI. A caller that only knows it wants the device powered on does not have to know
    /// either.
    /// </para>
    /// </remarks>
    public void TurnDeviceOn()
    {
        SendMessage(ScpiMessageProducer.TurnDeviceOn);
    }

    // SD and LAN share one SPI bus and can't both be enabled (hardware limitation).
    // Core owns the LAN-disable/SD-enable SCPI pair; the desktop only adds the USB-only
    // stream-interface switch (Core's base method omits it by design).
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.PrepareSdInterface
    private void PrepareSdInterface()
    {
        var coreDevice = GetConnectedCoreDevice(CoreDeviceForNetworkConfiguration);
        coreDevice.PrepareSdInterface();

        if (ConnectionType == ConnectionType.Usb)
        {
            SendMessage(ScpiMessageProducer.SetStreamInterface(StreamInterface.SdCard));
        }
    }

    // SD and LAN share one SPI bus and can't both be enabled (hardware limitation).
    // Core owns the SD-disable/LAN-enable SCPI pair; the desktop only adds the USB-only
    // stream-interface switch (Core's base method omits it by design).
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.PrepareLanInterface
    private void PrepareLanInterface()
    {
        var coreDevice = GetConnectedCoreDevice(CoreDeviceForNetworkConfiguration);
        coreDevice.PrepareLanInterface();

        if (ConnectionType == ConnectionType.Usb)
        {
            SendMessage(ScpiMessageProducer.SetStreamInterface(StreamInterface.Usb));
        }
    }

    #region Debug Mode Methods
    /// <summary>
    /// Sets the debug mode for this device
    /// </summary>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.SetDebugMode
    public void SetDebugMode(bool enabled)
    {
        IsDebugModeEnabled = enabled;
        AppLogger.Information($"[DEBUG_MODE] Device {DeviceSerialNo}: Debug mode {(enabled ? "enabled" : "disabled")}");
    }

    /// <summary>
    /// Creates and sends debug data when in debug mode
    /// </summary>
    // @port: Daqifi.Desktop.Device.AbstractStreamingDevice.SendDebugData
    private void SendDebugData(DaqifiOutMessage message, List<AnalogChannel> activeChannels, DateTime timestamp)
    {
        if (!IsDebugModeEnabled) return;

        try
        {
            var debugData = new DebugDataModel
            {
                Timestamp = timestamp,
                DeviceId = DeviceSerialNo,
                AnalogDataCount = message.AnalogInData.Count,
                RawAnalogValues = message.AnalogInData.ToList(),
                ActiveChannelNames = activeChannels.Select(c => c.Name).ToList(),
                ActiveChannelIndices = activeChannels.Select(c => c.Index).ToList()
            };

            // Calculate current channel enable mask
            var enableMask = 0;
            foreach (var channel in DataChannels.Where(c => c.IsActive && c.Type == ChannelType.Analog))
            {
                enableMask |= (1 << channel.Index);
            }
            debugData.ChannelEnableMask = enableMask.ToString(CultureInfo.InvariantCulture);
            debugData.ChannelEnableBinary = Convert.ToString(enableMask, 2);

            // Calculate scaled values
            debugData.ScaledAnalogValues = [];
            for (var i = 0; i < Math.Min(message.AnalogInData.Count, activeChannels.Count); i++)
            {
                var channel = activeChannels[i];
                var rawValue = message.AnalogInData[i];
                // Use core's scaling implementation for correct formula and thread-safety
                var scaledValue = channel.GetScaledValue((int)rawValue);
                debugData.ScaledAnalogValues.Add(scaledValue);
            }

            // Log the debug information
            AppLogger.Information(debugData.LogSummary);

            // Notify subscribers
            DebugDataReceived?.Invoke(debugData);
        }
        catch (Exception ex)
        {
            // Same shape as the two decode paths: reached once per streamed message whenever
            // debug mode is on, so it gets the same exception-preserving, throttled report.
            ReportStreamProcessingFailure(
                ref _debugDataFailureCount, ex, "[DEBUG_MODE] Error creating debug data");
        }
    }
    #endregion
}
